import { useState, useEffect, Suspense, lazy } from 'react';
import { useTranslation } from 'react-i18next';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import MedicalDisclaimer from './components/MedicalDisclaimer';
import Header from './components/Header';
import { changelogEntries } from './utils/changelogData';
import { AppProvider } from './context/AppContext.tsx';
import { useAppContext } from './context/useAppContext';
import type { TabId } from './context/AppContextTypes';
import { useToast } from './hooks/useToast';
import { Toast } from './components/Toast';

const SEEN_VERSION_KEY = 'foodmapper_seen_changelog_version';

// Lazy-loaded route components for code-splitting
const NutritionalCalculator = lazy(() => import('./components/NutritionalCalculator'));
const EducationalHub = lazy(() => import('./components/EducationalHub'));
const FoodFilter = lazy(() => import('./components/FoodFilter'));
const DietPlan = lazy(() => import('./components/DietPlan'));
const Diary = lazy(() => import('./components/Diary'));
const WorkoutPlan = lazy(() => import('./components/WorkoutPlan'));
const Recipes = lazy(() => import('./components/Recipes'));
const ShoppingList = lazy(() => import('./components/ShoppingList'));
const Changelog = lazy(() => import('./components/Changelog'));
const DeveloperCard = lazy(() => import('./components/DeveloperCard'));
const RecipeDetail = lazy(() => import('./components/RecipeDetail'));
const SleepTracker = lazy(() => import('./components/SleepTracker'));

const LoadingFallback = () => (
  <div className="flex items-center justify-center min-h-75">
    <div className="animate-spin rounded-full h-10 w-10 border-3 border-(--accent) border-t-transparent" aria-label="Loading..." />
  </div>
);

const TABS: { id: TabId; icon: string; labelKey: string }[] = [
  { id: 'calc', icon: '⚙️', labelKey: 'tab_calc' },
  { id: 'diary', icon: '📔', labelKey: 'tab_diary' },
  { id: 'diet', icon: '🍽️', labelKey: 'tab_diet' },
  { id: 'recipes', icon: '📖', labelKey: 'tab_recipes' },
  { id: 'shopping', icon: '🛒', labelKey: 'tab_shopping' },
  { id: 'workout', icon: '💪', labelKey: 'tab_workout' },
  { id: 'sleep', icon: '🌙', labelKey: 'tab_sleep' },
  { id: 'foods', icon: '🔍', labelKey: 'tab_foods' },
  { id: 'hub', icon: '📚', labelKey: 'tab_hub' },
  { id: 'changelog', icon: '📋', labelKey: 'tab_changelog' },
  { id: 'developer', icon: '👨‍💻', labelKey: 'tab_developer' }
];

export default function App() {
  return (
    <BrowserRouter>
      <AppProvider>
        <AppContent />
      </AppProvider>
    </BrowserRouter>
  );
}

function AppContent() {
  const { t } = useTranslation();
  const { calcResults, handleCalculate } = useAppContext();
  const [isAppUnlocked, setIsAppUnlocked] = useState(false);
  const [hasNewChangelog, setHasNewChangelog] = useState(false);
  const { toasts, removeToast } = useToast();

  useEffect(() => {
    try {
      const latestVersion = changelogEntries[0]?.version;
      const seenVersion = localStorage.getItem(SEEN_VERSION_KEY);
      if (latestVersion && seenVersion !== latestVersion) {
        setHasNewChangelog(true);
      } else {
        setHasNewChangelog(false);
      }
    } catch {
      setHasNewChangelog(false);
    }
  }, []);

  return (
    <div className="flex flex-col p-2 sm:p-4 md:p-6 lg:p-8 max-w-full">
      <MedicalDisclaimer onAccept={() => setIsAppUnlocked(true)} />

      {isAppUnlocked && (
        <div className="w-full mt-8">
          <Header />

          {/* Navigazione a schede: centrata e responsiva senza overflow laterale. */}
          <nav className="w-full mx-auto px-4 sm:px-6 md:px-8 mb-4">
            <div className="grid grid-cols-2 sm:grid-cols-4 lg:flex lg:flex-wrap justify-center gap-2 md:gap-3 pb-3">
              {TABS.map(tab => {
                const showBadge = tab.id === 'changelog' && hasNewChangelog;
                return (
                  <button
                    key={tab.id}
                    onClick={() => {
                      window.history.pushState(null, '', `/${tab.id}`);
                      window.dispatchEvent(new PopStateEvent('popstate'));
                    }}
                    className={`relative flex min-w-0 items-center gap-1.5 sm:gap-2 px-3 sm:px-4 md:px-5 py-2 sm:py-2.5 rounded-xl text-xs sm:text-sm md:text-base font-semibold whitespace-nowrap border transition-all cursor-pointer ${
                      window.location.pathname === `/${tab.id}` || (tab.id === 'calc' && window.location.pathname === '/')
                        ? 'bg-(--accent) text-white border-(--accent) shadow-md'
                        : 'bg-(--bg) border-(--border) text-(--text) hover:text-(--text-h) hover:border-(--accent-border)'
                    }`}
                  >
                    <span aria-hidden="true">{tab.icon}</span>
                    {t(tab.labelKey)}
                    {showBadge && (
                      <span
                        className="w-2.5 h-2.5 bg-red-500 rounded-full inline-block animate-pulse ml-1"
                        aria-label="Nuova versione disponibile"
                      />
                    )}
                  </button>
                );
              })}
            </div>
          </nav>

          <main className="w-full">
            <Suspense fallback={<LoadingFallback />}>
              <Routes>
                              <Route path="/" element={<Navigate to="/calc" replace />} />
                              <Route path="/calc" element={<NutritionalCalculator onCalculate={handleCalculate} initialResults={calcResults} />} />
                              <Route path="/diary" element={<Diary waterTargetLiters={calcResults?.waterLiters ?? null} nutritionalResults={calcResults} />} />
                              <Route path="/diet" element={<DietPlan />} />
                              <Route path="/recipes" element={<Recipes />} />
                              <Route path="/recipes/:recipeId" element={<RecipeDetail />} />
                              <Route path="/shopping" element={<ShoppingList />} />
                              <Route path="/workout" element={<WorkoutPlan />} />
                              <Route path="/sleep" element={<SleepTracker />} />
                              <Route path="/foods" element={<FoodFilter />} />
                              <Route path="/hub" element={<EducationalHub />} />
                              <Route path="/changelog" element={<Changelog />} />
                              <Route path="/developer" element={<DeveloperCard />} />
                              <Route path="*" element={<Navigate to="/calc" replace />} />
                            </Routes>
            </Suspense>
          </main>
        </div>
      )}

      {/* Toast notifications */}
      <div className="fixed bottom-4 right-4 z-50 flex flex-col gap-2 pointer-events-none">
        {toasts.map(toast => (
          <Toast
            key={toast.id}
            message={toast.message}
            type={toast.type}
            onClose={() => removeToast(toast.id)}
          />
        ))}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { usePreloadExerciseGifs, EXERCISE_GIF_URLS, getExerciseGifUrl } from '../utils/exerciseGifHelpers';

interface ExerciseGifProps {
  exerciseId: string;
  gifUrl?: string;
  fallbackImageUrl?: string;
  alt?: string;
  className?: string;
  width?: number;
  height?: number;
}

/**
 * Componente per mostrare GIF animate degli esercizi con lazy loading e fallback.
 * Supporta GIF da URL esterni (GitHub raw, CDN) o asset locali.
 * Fallback a immagine statica se la GIF non è disponibile.
 */
export default function ExerciseGif({
  exerciseId,
  gifUrl,
  fallbackImageUrl,
  alt,
  className = 'max-w-xs sm:max-w-md mx-auto',
  width,
  height,
}: ExerciseGifProps) {
  // useTranslation moved to top level — before any early returns or conditionals
  const { t } = useTranslation();

  const [imageSrc, setImageSrc] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);
  const [useFallback, setUseFallback] = useState(false);

  // URL di default per le GIF degli esercizi (placeholder - da sostituire con URL reali)
  const DEFAULT_GIF_BASE = 'https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExcG5wYzJwYzJwYzJw/giphy.gif';
  const DEFAULT_FALLBACK_BASE = 'https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExcG5wYzJwYzJwYzJw/giphy.gif';

  useEffect(() => {
    let mounted = true;
    let image: HTMLImageElement | null = null;

    const loadImage = async (src: string, isFallback = false) => {
      if (!mounted) return;
      
      setIsLoading(true);
      image = new Image();
      
      image.onload = () => {
        if (mounted) {
          setImageSrc(src);
          setIsLoading(false);
          setHasError(false);
        }
      };
      
      image.onerror = () => {
        if (mounted) {
          if (!isFallback && fallbackImageUrl) {
            // Prova con l'immagine di fallback personalizzata
            loadImage(fallbackImageUrl, true);
          } else if (!isFallback && !useFallback) {
            // Prova con l'immagine di fallback di default
            const defaultFallback = `${DEFAULT_FALLBACK_BASE}/${exerciseId}.png`;
            setUseFallback(true);
            loadImage(defaultFallback, true);
          } else {
            setHasError(true);
            setIsLoading(false);
          }
        }
      };
      
      image.src = src;
    };

    // Determina quale GIF caricare
    const gifToLoad = gifUrl || `${DEFAULT_GIF_BASE}/${exerciseId}.gif`;
    loadImage(gifToLoad);

    return () => {
      mounted = false;
      if (image) {
        image.onload = null;
        image.onerror = null;
        image.src = '';
      }
    };
  }, [exerciseId, gifUrl, fallbackImageUrl, useFallback]);

  if (isLoading) {
    return (
      <div 
        className={`${className} relative bg-(--code-bg) border border-(--border) rounded-xl overflow-hidden animate-pulse`}
        style={{ width, height: height || 200, minHeight: 150 }}
        aria-label="Caricamento animazione esercizio..."
      >
        <div className="absolute inset-0 flex items-center justify-center">
          <svg className="w-8 h-8 text-(--text) opacity-50" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
          </svg>
        </div>
      </div>
    );
  }

  if (hasError) {
    return (
      <div
        className={`${className} relative bg-(--code-bg) border border-(--border) rounded-xl overflow-hidden`}
        style={{ width, height: height || 200, minHeight: 150 }}
        aria-label={alt || `Esercizio: ${exerciseId}`}
      >
        <div className="absolute inset-0 flex flex-col items-center justify-center p-4 text-center">
          <svg className="w-12 h-12 text-(--text) opacity-30 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
          </svg>
          <p className="text-xs text-(--text) opacity-60">{t('exercise.gif_unavailable')}</p>
        </div>
      </div>
    );
  }

  return (
    <div 
      className={`${className} relative bg-(--code-bg) border border-(--border) rounded-xl overflow-hidden`}
      style={{ width, height: height || 200, minHeight: 150 }}
    >
      {imageSrc && (
        <img
          src={imageSrc}
          alt={alt || `Dimostrazione esercizio ${exerciseId}`}
          className="w-full h-full object-cover transition-opacity duration-300"
          loading="lazy"
          width={width}
          height={height}
        />
      )}
      {useFallback && imageSrc && (
        <div className="absolute bottom-2 right-2 px-2 py-1 text-xs bg-black/50 text-white rounded">
          Immagine statica
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate, useParams, Link } from 'react-router-dom';
import { useAppContext } from '../context/useAppContext';
import { useRecipes } from '../hooks/useRecipes';
import { FOODS_DATABASE } from '../utils/foodsData';
import {
  RECIPES_DATABASE,
  calculateRecipeMacros,
  isRecipeLowFODMAP,
  getRecipeSeasons,
  getRecipeProteins,
  DIFFICULTY_COLORS,
  DIFFICULTY_LABELS,
  RECIPE_CATEGORY_MAP,
} from '../utils/recipesData';
import InfoPopup from './InfoPopup';
import type { Recipe, MealPortion } from '../types/dietPlan';

interface RecipeDetailProps {
  recipeId?: string;
}

export default function RecipeDetail({ recipeId: propRecipeId }: RecipeDetailProps) {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const { userData } = useAppContext();
  const { recipes: userRecipes, deleteRecipe } = useRecipes({ userData });
  const { recipeId: paramRecipeId } = useParams<{ recipeId: string }>();
  const recipeId = propRecipeId || paramRecipeId;

  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [showFoodModal, setShowFoodModal] = useState<string | null>(null);
  const [selectedPortion, setSelectedPortion] = useState<MealPortion | null>(null);
  const [activeTab, setActiveTab] = useState<'details' | 'nutrition' | 'instructions'>('details');
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  // Load recipe on mount
  useEffect(() => {
    if (!recipeId) {
      navigate('/recipes');
      return;
    }

    const loadRecipe = () => {
      setIsLoading(true);
      // First check user recipes
      let foundRecipe = userRecipes.find(r => r.id === recipeId);
      
      // Then check predefined recipes database
      if (!foundRecipe) {
        const predefinedIndex = RECIPES_DATABASE.findIndex((_, i) => `predefined-${i}` === recipeId);
        if (predefinedIndex >= 0) {
          const predefined = RECIPES_DATABASE[predefinedIndex];
          foundRecipe = {
            ...predefined,
            id: `predefined-${predefinedIndex}`,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
          } as Recipe;
        }
      }

      if (foundRecipe) {
        setRecipe(foundRecipe);
      } else {
        // Recipe not found
        setToast({ message: t('recipes.not_found', { defaultValue: 'Ricetta non trovata' }), type: 'error' });
        setTimeout(() => navigate('/recipes'), 2000);
      }
      setIsLoading(false);
    };

    loadRecipe();
  }, [recipeId, userRecipes, navigate, t]);

  // Show toast
  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const handleAddToShoppingList = useCallback(() => {
    // Navigate to shopping list with recipe ingredients
    navigate('/shopping', { state: { recipeIngredients: recipe.portions } });
    setToast({ message: t('recipes.added_to_shopping', { defaultValue: 'Ingredienti aggiunti alla lista spesa' }), type: 'success' });
  }, [navigate, recipe, t]);

  const handleAddToDietPlan = useCallback(() => {
    // Navigate to diet plan with recipe
    navigate('/diet', { state: { recipeToAdd: recipe } });
    setToast({ message: t('recipes.added_to_diet', { defaultValue: 'Ricetta aggiunta al piano alimentare' }), type: 'success' });
  }, [navigate, recipe, t]);

  const handleEditRecipe = useCallback(() => {
    // Navigate to recipes tab with edit mode
    navigate('/recipes', { state: { editRecipeId: recipe.id } });
  }, [navigate, recipe.id]);

  const handleDeleteRecipe = useCallback(() => {
    if (window.confirm(t('recipes.confirm_delete', { defaultValue: 'Sei sicuro di voler eliminare questa ricetta?' }))) {
      if (recipe.id.startsWith('predefined-')) {
        setToast({ message: t('recipes.cannot_delete_predefined', { defaultValue: 'Non puoi eliminare le ricette predefinite' }), type: 'error' });
      } else {
        deleteRecipe(recipe.id);
        setToast({ message: t('recipes.deleted', { defaultValue: 'Ricetta eliminata' }), type: 'success' });
        setTimeout(() => navigate('/recipes'), 1000);
      }
    }
  }, [recipe, deleteRecipe, navigate, t]);

  const openFoodDetail = useCallback((portion: MealPortion) => {
    setSelectedPortion(portion);
    setShowFoodModal(portion.foodId);
  }, []);

  const closeFoodModal = useCallback(() => {
    setShowFoodModal(null);
    setSelectedPortion(null);
  }, []);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="animate-spin rounded-full h-10 w-10 border-3 border-(--accent) border-t-transparent" aria-label={t('common.loading', { defaultValue: 'Caricamento...' })} />
      </div>
    );
  }

  if (!recipe) {
    return null;
  }

  const macros = calculateRecipeMacros(recipe);
  const isLowFODMAP = isRecipeLowFODMAP(recipe);
  const seasons = getRecipeSeasons(recipe);
  const proteins = getRecipeProteins(recipe);
  const category = RECIPE_CATEGORY_MAP[recipe.name] || 'Altro';
  const difficultyColor = DIFFICULTY_COLORS[recipe.difficulty];
  const difficultyLabel = DIFFICULTY_LABELS[recipe.difficulty];

  const monthNames = [
    '', t('months.jan', { defaultValue: 'Gen' }), t('months.feb', { defaultValue: 'Feb' }),
    t('months.mar', { defaultValue: 'Mar' }), t('months.apr', { defaultValue: 'Apr' }),
    t('months.may', { defaultValue: 'Mag' }), t('months.jun', { defaultValue: 'Giu' }),
    t('months.jul', { defaultValue: 'Lug' }), t('months.aug', { defaultValue: 'Ago' }),
    t('months.sep', { defaultValue: 'Set' }), t('months.oct', { defaultValue: 'Ott' }),
    t('months.nov', { defaultValue: 'Nov' }), t('months.dec', { defaultValue: 'Dic' })
  ];

  const seasonLabels = seasons.map(m => monthNames[m]).join(', ');

  const getFoodItem = (foodId: string) => FOODS_DATABASE.find(f => f.id === foodId);

  const formatTime = (minutes: number) => {
    if (minutes < 60) return `${minutes} min`;
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return mins > 0 ? `${hours}h ${mins}min` : `${hours}h`;
  };

  const totalTime = recipe.prepTimeMinutes + recipe.cookTimeMinutes;

  return (
    <div className="w-full max-w-4xl mx-auto px-4 sm:px-6 md:px-8 py-4 sm:py-6">
      {/* Back button */}
      <Link
        to="/recipes"
        className="inline-flex items-center gap-2 text-(--accent) hover:underline mb-4 sm:mb-6"
      >
        ← {t('recipes.back_to_list', { defaultValue: 'Torna alle ricette' })}
      </Link>

      {toast && (
        <div className={`mb-4 p-3 rounded-lg text-sm ${toast.type === 'success' ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400' : 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400'}`}>
          {toast.message}
        </div>
      )}

      {/* Hero Image */}
      {recipe.photoUrl && (
        <div className="relative h-64 sm:h-80 md:h-96 rounded-xl overflow-hidden mb-6">
          <img
            src={recipe.photoUrl}
            alt={recipe.name}
            className="w-full h-full object-cover"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent" />
          <div className="absolute bottom-4 left-4 right-4 text-white">
            <h1 className="text-2xl sm:text-3xl font-bold">{recipe.name}</h1>
            <div className="flex flex-wrap gap-3 mt-2 text-sm">
              <span className={`px-2 py-1 rounded-full ${difficultyColor}`}>
                {t(`recipes.difficulty.${recipe.difficulty}`, { defaultValue: difficultyLabel.it })}
              </span>
              <span className="px-2 py-1 rounded-full bg-white/20 backdrop-blur">
                {t('recipes.category', { defaultValue: 'Categoria' })}: {category}
              </span>
              {isLowFODMAP && (
                <span className="px-2 py-1 rounded-full bg-green-500/20 text-green-300 border border-green-500/30">
                  {t('recipes.low_fodmap', { defaultValue: 'Low-FODMAP' })}
                </span>
              )}
            </div>
          </div>
        </div>
      )}

      {!recipe.photoUrl && (
        <div className="mb-6">
          <h1 className="text-2xl sm:text-3xl font-bold text-(--text-h) mb-2">{recipe.name}</h1>
          <div className="flex flex-wrap gap-3 text-sm">
            <span className={`px-2 py-1 rounded-full ${difficultyColor}`}>
              {t(`recipes.difficulty.${recipe.difficulty}`, { defaultValue: difficultyLabel.it })}
            </span>
            <span className="px-2 py-1 rounded-full bg-(--code-bg) text-(--text-h)">
              {t('recipes.category', { defaultValue: 'Categoria' })}: {category}
            </span>
            {isLowFODMAP && (
              <span className="px-2 py-1 rounded-full bg-green-500/20 text-green-300 border border-green-500/30">
                {t('recipes.low_fodmap', { defaultValue: 'Low-FODMAP' })}
              </span>
            )}
          </div>
        </div>
      )}

      {/* Quick Stats Bar */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 sm:gap-4 mb-6 p-4 bg-(--bg) border border-(--border) rounded-xl">
        <div className="text-center">
          <div className="text-2xl sm:text-3xl font-bold text-(--accent)">{recipe.servings}</div>
          <div className="text-xs text-(--text)">{t('recipes.servings', { defaultValue: 'Porzioni' })}</div>
        </div>
        <div className="text-center border-l border-(--border) pl-3 sm:pl-4">
          <div className="text-2xl sm:text-3xl font-bold text-(--text-h)">{formatTime(recipe.prepTimeMinutes)}</div>
          <div className="text-xs text-(--text)">{t('recipes.prep_time', { defaultValue: 'Preparazione' })}</div>
        </div>
        <div className="text-center border-l border-(--border) pl-3 sm:pl-4">
          <div className="text-2xl sm:text-3xl font-bold text-(--text-h)">{formatTime(recipe.cookTimeMinutes)}</div>
          <div className="text-xs text-(--text)">{t('recipes.cook_time', { defaultValue: 'Cottura' })}</div>
        </div>
        <div className="text-center border-l border-(--border) pl-3 sm:pl-4">
          <div className="text-2xl sm:text-3xl font-bold text-(--text-h)">{formatTime(totalTime)}</div>
          <div className="text-xs text-(--text)">{t('recipes.total_time', { defaultValue: 'Totale' })}</div>
        </div>
      </div>

      {/* Macro Summary Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-6">
        <div className="bg-(--bg) border border-(--border) rounded-xl p-4 text-center">
          <div className="text-2xl sm:text-3xl font-bold text-(--accent)">{macros.perServing.calories}</div>
          <div className="text-xs text-(--text)">{t('recipes.calories', { defaultValue: 'Calorie' })}</div>
          <div className="text-xs text-(--text-h) mt-1">{t('recipes.per_serving', { defaultValue: 'per porzione' })}</div>
        </div>
        <div className="bg-(--bg) border border-(--border) rounded-xl p-4 text-center">
          <div className="text-2xl sm:text-3xl font-bold text-blue-500">{macros.perServing.protein}g</div>
          <div className="text-xs text-(--text)">{t('recipes.protein', { defaultValue: 'Proteine' })}</div>
          <div className="text-xs text-(--text-h) mt-1">{t('recipes.per_serving', { defaultValue: 'per porzione' })}</div>
        </div>
        <div className="bg-(--bg) border border-(--border) rounded-xl p-4 text-center">
          <div className="text-2xl sm:text-3xl font-bold text-amber-500">{macros.perServing.carbs}g</div>
          <div className="text-xs text-(--text)">{t('recipes.carbs', { defaultValue: 'Carboidrati' })}</div>
          <div className="text-xs text-(--text-h) mt-1">{t('recipes.per_serving', { defaultValue: 'per porzione' })}</div>
        </div>
        <div className="bg-(--bg) border border-(--border) rounded-xl p-4 text-center">
          <div className="text-2xl sm:text-3xl font-bold text-rose-500">{macros.perServing.fat}g</div>
          <div className="text-xs text-(--text)">{t('recipes.fat', { defaultValue: 'Grassi' })}</div>
          <div className="text-xs text-(--text-h) mt-1">{t('recipes.per_serving', { defaultValue: 'per porzione' })}</div>
        </div>
      </div>

      {/* Tabs */}
      <div className="border-b border-(--border) mb-6">
        <nav className="flex gap-1" role="tablist">
          {[
            { id: 'details', label: t('recipes.tab_details', { defaultValue: 'Dettagli' }) },
            { id: 'nutrition', label: t('recipes.tab_nutrition', { defaultValue: 'Nutrizione' }) },
            { id: 'instructions', label: t('recipes.tab_instructions', { defaultValue: 'Preparazione' }) },
          ].map(tab => (
            <button
              key={tab.id}
              role="tab"
              aria-selected={activeTab === tab.id}
              onClick={() => setActiveTab(tab.id as typeof activeTab)}
              className={`px-4 py-2 text-sm font-medium rounded-t-lg transition-colors ${
                activeTab === tab.id
                  ? 'bg-(--accent) text-white'
                  : 'text-(--text) hover:text-(--text-h) hover:bg-(--code-bg)'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </nav>
      </div>

      {/* Tab Content */}
      <div className="space-y-6">
        {/* DETAILS TAB */}
        {activeTab === 'details' && (
          <div className="space-y-6">
            {/* Ingredients */}
            <section>
              <h2 className="text-lg font-semibold text-(--text-h) mb-4 flex items-center gap-2">
                {t('recipes.ingredients', { defaultValue: 'Ingredienti' })}
                <InfoPopup infoKey="recipe_ingredients" className="ml-1.5" />
              </h2>
              <div className="space-y-2">
                {recipe.portions.map((portion) => {
                  const food = getFoodItem(portion.foodId);
                  const isProblematic = food && food.fodmapLevel === 'high';
                  return (
                    <div
                      key={portion.foodId}
                      className={`flex items-center gap-3 p-3 rounded-lg border transition-colors ${
                        isProblematic ? 'border-amber-300 bg-amber-50 dark:bg-amber-900/20' : 'border-(--border) bg-(--bg) hover:bg-(--code-bg)/50'
                      }`}
                      onClick={() => openFoodDetail(portion)}
                      style={{ cursor: 'pointer' }}
                    >
                      <div className="w-10 h-10 rounded-lg bg-(--accent)/10 flex items-center justify-center flex-shrink-0">
                        <span className="text-lg">{food ? getFoodEmoji(food.category) : '🍽️'}</span>
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="font-medium text-(--text-h) truncate">{portion.foodName}</span>
                          {isProblematic && (
                            <span className="px-1.5 py-0.5 text-xs rounded bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400">
                              {t('recipes.high_fodmap', { defaultValue: 'High FODMAP' })}
                            </span>
                          )}
                          {food?.triggerGroup && (
                            <span className="px-1.5 py-0.5 text-xs rounded bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400">
                              {food.triggerGroup}
                            </span>
                          )}
                        </div>
                        <div className="text-sm text-(--text)">
                          {portion.grams}g · {portion.nutrition.calories} kcal · P: {portion.nutrition.protein}g C: {portion.nutrition.carbs}g F: {portion.nutrition.fat}g
                        </div>
                      </div>
                      <div className="text-(--accent) font-medium">
                        {t('recipes.click_for_details', { defaultValue: 'Dettagli →' })}
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>

            {/* Recipe Info */}
            <section className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="bg-(--bg) border border-(--border) rounded-xl p-4">
                <h3 className="font-medium text-(--text-h) mb-3">{t('recipes.info', { defaultValue: 'Informazioni' })}</h3>
                <dl className="space-y-3 text-sm">
                  <div className="flex justify-between">
                    <dt className="text-(--text)">{t('recipes.servings', { defaultValue: 'Porzioni' })}</dt>
                    <dd className="font-medium text-(--text-h)">{recipe.servings}</dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-(--text)">{t('recipes.difficulty_label', { defaultValue: 'Difficoltà' })}</dt>
                    <dd className="font-medium text-(--text-h)">
                      <span className={`px-2 py-0.5 rounded text-xs ${difficultyColor}`}>
                        {t(`recipes.difficulty.${recipe.difficulty}`, { defaultValue: difficultyLabel.it })}
                      </span>
                    </dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-(--text)">{t('recipes.category', { defaultValue: 'Categoria' })}</dt>
                    <dd className="font-medium text-(--text-h)">{category}</dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-(--text)">{t('recipes.meal_type', { defaultValue: 'Tipo pasto' })}</dt>
                    <dd className="font-medium text-(--text-h) capitalize">{recipe.mealType}</dd>
                  </div>
                  {seasonLabels && (
                    <div className="flex justify-between">
                      <dt className="text-(--text)">{t('recipes.seasonality', { defaultValue: 'Stagionalità' })}</dt>
                      <dd className="font-medium text-(--text-h)">{seasonLabels}</dd>
                    </div>
                  )}
                  {proteins.length > 0 && (
                    <div className="flex justify-between">
                      <dt className="text-(--text)">{t('recipes.main_proteins', { defaultValue: 'Proteine principali' })}</dt>
                      <dd className="font-medium text-(--text-h)">{proteins.join(', ')}</dd>
                    </div>
                  )}
                  {recipe.tags.length > 0 && (
                    <div className="flex justify-between">
                      <dt className="text-(--text)">{t('recipes.tags', { defaultValue: 'Tag' })}</dt>
                      <dd className="font-medium text-(--text-h)">
                        <div className="flex flex-wrap gap-1">
                          {recipe.tags.map(tag => (
                            <span key={tag} className="px-2 py-0.5 text-xs rounded bg-(--code-bg) text-(--text-h)">
                              {tag}
                            </span>
                          ))}
                        </div>
                      </dd>
                    </div>
                  )}
                </dl>
              </div>

              <div className="bg-(--bg) border border-(--border) rounded-xl p-4">
                <h3 className="font-medium text-(--text-h) mb-3">{t('recipes.macros_total', { defaultValue: 'Macro Totali (ricetta intera)' })}</h3>
                <dl className="space-y-2 text-sm">
                  <div className="flex justify-between"><dt className="text-(--text)">{t('recipes.calories', { defaultValue: 'Calorie' })}</dt><dd className="font-bold text-(--text-h)">{macros.total.calories} kcal</dd></div>
                  <div className="flex justify-between"><dt className="text-(--text)">{t('recipes.protein', { defaultValue: 'Proteine' })}</dt><dd className="font-bold text-blue-500">{macros.total.protein}g</dd></div>
                  <div className="flex justify-between"><dt className="text-(--text)">{t('recipes.carbs', { defaultValue: 'Carboidrati' })}</dt><dd className="font-bold text-amber-500">{macros.total.carbs}g</dd></div>
                  <div className="flex justify-between"><dt className="text-(--text)">{t('recipes.fat', { defaultValue: 'Grassi' })}</dt><dd className="font-bold text-rose-500">{macros.total.fat}g</dd></div>
                  <div className="flex justify-between"><dt className="text-(--text)">{t('recipes.fiber', { defaultValue: 'Fibre' })}</dt><dd className="font-bold text-green-500">{macros.total.fiber}g</dd></div>
                  <div className="flex justify-between"><dt className="text-(--text)">{t('recipes.sugar', { defaultValue: 'Zuccheri' })}</dt><dd className="font-bold text-orange-500">{macros.total.sugar}g</dd></div>
                  <div className="flex justify-between"><dt className="text-(--text)">{t('recipes.sodium', { defaultValue: 'Sodio' })}</dt><dd className="font-bold text-(--text-h)">{macros.total.sodium}mg</dd></div>
                </dl>
              </div>
            </section>

            {/* Actions */}
            <section className="flex flex-wrap gap-3 pt-4 border-t border-(--border)">
              <button
                onClick={handleAddToShoppingList}
                className="flex-1 sm:flex-none px-4 py-2.5 rounded-lg bg-(--accent) text-white font-medium hover:bg-(--accent)/90 transition-colors"
              >
                🛒 {t('recipes.add_to_shopping', { defaultValue: 'Aggiungi a Shopping List' })}
              </button>
              <button
                onClick={handleAddToDietPlan}
                className="flex-1 sm:flex-none px-4 py-2.5 rounded-lg border border-(--accent) text-(--accent) font-medium hover:bg-(--accent)/10 transition-colors"
              >
                🍽️ {t('recipes.add_to_diet', { defaultValue: 'Aggiungi a Piano Alimentare' })}
              </button>
              {recipe.isCustom && (
                <>
                  <button
                    onClick={handleEditRecipe}
                    className="flex-1 sm:flex-none px-4 py-2.5 rounded-lg border border-(--border) text-(--text-h) font-medium hover:bg-(--code-bg) transition-colors"
                  >
                    ✏️ {t('recipes.edit', { defaultValue: 'Modifica' })}
                  </button>
                  <button
                    onClick={handleDeleteRecipe}
                    className="flex-1 sm:flex-none px-4 py-2.5 rounded-lg border border-red-500 text-red-500 font-medium hover:bg-red-500/10 transition-colors"
                  >
                    🗑️ {t('recipes.delete', { defaultValue: 'Elimina' })}
                  </button>
                </>
              )}
            </section>
          </div>
        )}

        {/* NUTRITION TAB */}
        {activeTab === 'nutrition' && (
          <div className="space-y-6">
            <section>
              <h2 className="text-lg font-semibold text-(--text-h) mb-4">{t('recipes.nutrition_per_serving', { defaultValue: 'Valori nutrizionali per porzione' })}</h2>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-(--border) text-left">
                      <th className="pb-2 text-(--text)">{t('recipes.nutrient', { defaultValue: 'Nutriente' })}</th>
                      <th className="pb-2 text-(--text) text-right">{t('recipes.per_serving', { defaultValue: 'Per porzione' })}</th>
                      <th className="pb-2 text-(--text) text-right">{t('recipes.total', { defaultValue: 'Totale' })}</th>
                      <th className="pb-2 text-(--text) text-right">{t('recipes.per_100g', { defaultValue: 'Per 100g' })}</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr className="border-b border-(--border)/50">
                      <td className="py-2 font-medium text-(--text-h)">{t('recipes.calories', { defaultValue: 'Energia' })}</td>
                      <td className="py-2 text-right font-bold text-(--accent)">{macros.perServing.calories} kcal</td>
                      <td className="py-2 text-right text-(--text)">{macros.total.calories} kcal</td>
                      <td className="py-2 text-right text-(--text)">{Math.round(macros.total.calories / (recipe.portions.reduce((s, p) => s + p.grams, 0) / 100))} kcal</td>
                    </tr>
                    <tr className="border-b border-(--border)/50">
                      <td className="py-2 font-medium text-(--text-h)">{t('recipes.protein', { defaultValue: 'Proteine' })}</td>
                      <td className="py-2 text-right font-bold text-blue-500">{macros.perServing.protein}g</td>
                      <td className="py-2 text-right text-(--text)">{macros.total.protein}g</td>
                      <td className="py-2 text-right text-(--text)">{Math.round((macros.total.protein / (recipe.portions.reduce((s, p) => s + p.grams, 0) / 100)) * 10) / 10}g</td>
                    </tr>
                    <tr className="border-b border-(--border)/50">
                      <td className="py-2 font-medium text-(--text-h)">{t('recipes.carbs', { defaultValue: 'Carboidrati' })}</td>
                      <td className="py-2 text-right font-bold text-amber-500">{macros.perServing.carbs}g</td>
                      <td className="py-2 text-right text-(--text)">{macros.total.carbs}g</td>
                      <td className="py-2 text-right text-(--text)">{Math.round((macros.total.carbs / (recipe.portions.reduce((s, p) => s + p.grams, 0) / 100)) * 10) / 10}g</td>
                    </tr>
                    <tr className="border-b border-(--border)/50">
                      <td className="py-2 font-medium text-(--text-h)">{t('recipes.fat', { defaultValue: 'Grassi' })}</td>
                      <td className="py-2 text-right font-bold text-rose-500">{macros.perServing.fat}g</td>
                      <td className="py-2 text-right text-(--text)">{macros.total.fat}g</td>
                      <td className="py-2 text-right text-(--text)">{Math.round((macros.total.fat / (recipe.portions.reduce((s, p) => s + p.grams, 0) / 100)) * 10) / 10}g</td>
                    </tr>
                    <tr className="border-b border-(--border)/50">
                      <td className="py-2 font-medium text-(--text-h)">{t('recipes.fiber', { defaultValue: 'Fibre' })}</td>
                      <td className="py-2 text-right font-bold text-green-500">{macros.perServing.fiber}g</td>
                      <td className="py-2 text-right text-(--text)">{macros.total.fiber}g</td>
                      <td className="py-2 text-right text-(--text)">{Math.round((macros.total.fiber / (recipe.portions.reduce((s, p) => s + p.grams, 0) / 100)) * 10) / 10}g</td>
                    </tr>
                    <tr className="border-b border-(--border)/50">
                      <td className="py-2 font-medium text-(--text-h)">{t('recipes.sugar', { defaultValue: 'Zuccheri' })}</td>
                      <td className="py-2 text-right font-bold text-orange-500">{macros.perServing.sugar}g</td>
                      <td className="py-2 text-right text-(--text)">{macros.total.sugar}g</td>
                      <td className="py-2 text-right text-(--text)">{Math.round((macros.total.sugar / (recipe.portions.reduce((s, p) => s + p.grams, 0) / 100)) * 10) / 10}g</td>
                    </tr>
                    <tr>
                      <td className="py-2 font-medium text-(--text-h)">{t('recipes.sodium', { defaultValue: 'Sodio' })}</td>
                      <td className="py-2 text-right font-bold text-(--text-h)">{macros.perServing.sodium}mg</td>
                      <td className="py-2 text-right text-(--text)">{macros.total.sodium}mg</td>
                      <td className="py-2 text-right text-(--text)">{Math.round((macros.total.sodium / (recipe.portions.reduce((s, p) => s + p.grams, 0) / 100)) * 10) / 10}mg</td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </section>

            {/* Micronutrients from ingredients */}
            <section>
              <h2 className="text-lg font-semibold text-(--text-h) mb-4">{t('recipes.micronutrients', { defaultValue: 'Micronutrienti principali' })}</h2>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                {getTopMicronutrients(recipe).map(([micro, value]) => (
                  <div key={micro} className="bg-(--bg) border border-(--border) rounded-lg p-3 text-center">
                    <div className="text-lg font-bold text-(--accent)">{value}</div>
                    <div className="text-xs text-(--text) capitalize">{micro.replace(/_/g, ' ')}</div>
                  </div>
                ))}
              </div>
            </section>
          </div>
        )}

        {/* INSTRUCTIONS TAB */}
        {activeTab === 'instructions' && (
          <div className="space-y-4">
            <ol className="space-y-4">
              {recipe.instructions.map((step, index) => (
                <li key={index} className="flex gap-3 p-4 bg-(--bg) border border-(--border) rounded-xl">
                  <span className="flex-shrink-0 w-8 h-8 rounded-full bg-(--accent) text-white flex items-center justify-center font-bold text-sm">
                    {index + 1}
                  </span>
                  <div className="flex-1 text-(--text-h) leading-relaxed">{step}</div>
                </li>
              ))}
            </ol>
            {recipe.instructions.length === 0 && (
              <p className="text-(--text) text-center py-8">{t('recipes.no_instructions', { defaultValue: 'Nessuna istruzione disponibile' })}</p>
            )}
          </div>
        )}
      </div>

      {/* Food Detail Modal */}
      {showFoodModal && selectedPortion && (
        <FoodDetailModal
          foodId={showFoodModal}
          portion={selectedPortion}
          onClose={closeFoodModal}
          t={t}
        />
      )}
    </div>
  );
}

/**
 * Modal per dettagli alimento (link a Food Database)
 */
function FoodDetailModal({ foodId, portion, onClose, t }: { foodId: string; portion: MealPortion; onClose: () => void; t: (key: string, options?: any) => string }) {
  const food = FOODS_DATABASE.find(f => f.id === foodId);
  if (!food) return null;

  const monthNames = [
    '', t('months.jan', { defaultValue: 'Gennaio' }), t('months.feb', { defaultValue: 'Febbraio' }),
    t('months.mar', { defaultValue: 'Marzo' }), t('months.apr', { defaultValue: 'Aprile' }),
    t('months.may', { defaultValue: 'Maggio' }), t('months.jun', { defaultValue: 'Giugno' }),
    t('months.jul', { defaultValue: 'Luglio' }), t('months.aug', { defaultValue: 'Agosto' }),
    t('months.sep', { defaultValue: 'Settembre' }), t('months.oct', { defaultValue: 'Ottobre' }),
    t('months.nov', { defaultValue: 'Novembre' }), t('months.dec', { defaultValue: 'Dicembre' })
  ];

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4"
      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
      role="dialog"
      aria-modal="true"
      aria-labelledby="food-detail-title"
    >
      <div className="bg-(--bg) rounded-xl shadow-xl w-full max-w-2xl max-h-[85vh] overflow-y-auto">
        <div className="sticky top-0 bg-(--bg) border-b border-(--border) p-4 flex justify-between items-center">
          <h2 id="food-detail-title" className="text-xl font-semibold text-(--text-h)">{food.name}</h2>
          <button onClick={onClose} className="text-(--text) hover:text-(--text-h) text-2xl leading-none" aria-label={t('common.close', { defaultValue: 'Chiudi' })}>×</button>
        </div>

        <div className="p-4 space-y-6">
          {/* Basic Info */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 p-3 bg-(--code-bg) rounded-lg">
            <div className="text-center">
              <div className="text-2xl font-bold text-(--accent)">{food.nutrition.kcal}</div>
              <div className="text-xs text-(--text)">{t('foods.kcal_per_100g', { defaultValue: 'kcal/100g' })}</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-blue-500">{food.nutrition.protein}g</div>
              <div className="text-xs text-(--text)">{t('foods.protein', { defaultValue: 'Proteine' })}</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-amber-500">{food.nutrition.carbs}g</div>
              <div className="text-xs text-(--text)">{t('foods.carbs', { defaultValue: 'Carboidrati' })}</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-rose-500">{food.nutrition.fats}g</div>
              <div className="text-xs text-(--text)">{t('foods.fats', { defaultValue: 'Grassi' })}</div>
            </div>
          </div>

          {/* FODMAP & Category */}
          <div className="flex flex-wrap gap-2">
            <span className={`px-3 py-1 rounded-full text-sm font-medium ${
              food.fodmapLevel === 'low' ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400' :
              food.fodmapLevel === 'medium' ? 'bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400' :
              'bg-rose-100 text-rose-800 dark:bg-rose-900/30 dark:text-rose-400'
            }`}>
              {food.fodmapLevel === 'low' ? t('foods.low_fodmap', { defaultValue: 'Low FODMAP' }) :
               food.fodmapLevel === 'medium' ? t('fodmap_details.medium_fodmap', { defaultValue: 'FODMAP Medio' }) :
               t('foods.high_fodmap', { defaultValue: 'High FODMAP' })}
            </span>
            {food.triggerGroup && (
              <span className="px-3 py-1 rounded-full text-sm bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400">
                {t(`fodmap_${food.triggerGroup}`)}
              </span>
            )}
            <span className="px-3 py-1 rounded-full text-sm bg-(--code-bg) text-(--text-h)">
              {t(`categories.${food.category}`)}
            </span>
            {food.months && (
              <span className="px-3 py-1 rounded-full text-sm bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-400">
                {t('foods.seasonal', { defaultValue: 'Stagionale' })}: {food.months.map(m => monthNames[m]).join(', ')}
              </span>
            )}
          </div>

          {/* Allergens */}
          {food.allergens && food.allergens.length > 0 && (
            <div>
              <h3 className="font-medium text-(--text-h) mb-2">{t('foods.allergens', { defaultValue: 'Allergeni' })}</h3>
              <div className="flex flex-wrap gap-2">
                {food.allergens.map(allergen => (
                  <span key={allergen} className="px-2 py-1 text-xs rounded bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400">
                    {allergen.replace('_', ' ')}
                  </span>
                ))}
              </div>
            </div>
          )}

          {/* Nutrition Details */}
          <div>
            <h3 className="font-medium text-(--text-h) mb-3">{t('foods.nutrition_details', { defaultValue: 'Dettagli nutrizionali per 100g' })}</h3>
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
              {[
                { key: 'fiber', label: t('foods.fiber', { defaultValue: 'Fibre' }), value: food.nutrition.fiber, unit: 'g' },
                { key: 'sugar', label: t('foods.sugar', { defaultValue: 'Zuccheri' }), value: food.nutrition.carbs * 0.1, unit: 'g' },
                ...Object.entries(food.nutrition.micronutrients || {}).map(([key, value]) => ({
                  key, label: t(`foods.micro.${key}`, { defaultValue: key.replace(/_/g, ' ') }), value, unit: getMicroUnit(key)
                }))
              ].filter(item => item.value && item.value > 0).map(item => (
                <div key={item.key} className="bg-(--code-bg) rounded-lg p-3 text-center">
                  <div className="text-lg font-bold text-(--text-h)">{typeof item.value === 'number' ? item.value.toFixed(item.value < 1 ? 2 : 0) : item.value}{item.unit}</div>
                  <div className="text-xs text-(--text)">{item.label}</div>
                </div>
              ))}
            </div>
          </div>

          {/* Portion Info */}
          <div className="p-3 rounded-lg border border-(--accent) bg-(--accent)/5">
            <h3 className="font-medium text-(--text-h) mb-2">{t('recipes.this_portion', { defaultValue: 'In questa porzione' })}</h3>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 text-sm">
              <div><span className="text-(--text)">{t('recipes.grams', { defaultValue: 'Peso' })}:</span> <span className="font-medium">{portion.grams}g</span></div>
              <div><span className="text-(--text)">{t('recipes.calories', { defaultValue: 'Calorie' })}:</span> <span className="font-medium">{portion.nutrition.calories} kcal</span></div>
              <div><span className="text-(--text)">{t('recipes.protein', { defaultValue: 'Proteine' })}:</span> <span className="font-medium text-blue-500">{portion.nutrition.protein}g</span></div>
              <div><span className="text-(--text)">{t('recipes.carbs', { defaultValue: 'Carboidrati' })}:</span> <span className="font-medium text-amber-500">{portion.nutrition.carbs}g</span></div>
              <div><span className="text-(--text)">{t('recipes.fat', { defaultValue: 'Grassi' })}:</span> <span className="font-medium text-rose-500">{portion.nutrition.fat}g</span></div>
              <div><span className="text-(--text)">{t('recipes.fiber', { defaultValue: 'Fibre' })}:</span> <span className="font-medium text-green-500">{portion.nutrition.fiber}g</span></div>
              <div><span className="text-(--text)">{t('recipes.sodium', { defaultValue: 'Sodio' })}:</span> <span className="font-medium">{portion.nutrition.sodium}mg</span></div>
            </div>
          </div>

          {/* Alternative */}
          {food.alternative && (
            <div className="p-3 rounded-lg bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800">
              <h3 className="font-medium text-blue-800 dark:text-blue-300 mb-1">{t('foods.alternative', { defaultValue: 'Alternativa low-FODMAP' })}</h3>
              <p className="text-sm text-blue-700 dark:text-blue-400">{food.alternative}</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function getFoodEmoji(category: string): string {
  switch (category) {
    case 'Carboidrati/Cereali': return '🌾';
    case 'Proteine/Formaggi': return '🥩';
    case 'Verdura': return '🥦';
    case 'Frutta': return '🍓';
    case 'Condimenti/Altro': return '🫒';
    default: return '🍽️';
  }
}

function getMicroUnit(key: string): string {
  const mgKeys = ['potassium', 'magnesium', 'calcium', 'iron', 'zinc', 'sodium', 'phosphorus', 'vitamin_c', 'vitamin_e', 'omega3'];
  const ugKeys = ['folate', 'vitamin_a', 'vitamin_d', 'b12', 'selenium', 'iodine', 'vitamin_k', 'vitamin_b6', 'manganese', 'copper'];
  if (mgKeys.includes(key)) return 'mg';
  if (ugKeys.includes(key)) return 'µg';
  return '';
}

function getTopMicronutrients(recipe: Recipe): [string, string][] {
  const microTotals: Record<string, number> = {};
  
  recipe.portions.forEach(portion => {
    const food = FOODS_DATABASE.find(f => f.id === portion.foodId);
    if (food?.microDetails) {
      Object.entries(food.microDetails).forEach(([key, value]) => {
        if (value && value > 0) {
          const factor = portion.grams / 100;
          microTotals[key] = (microTotals[key] || 0) + value * factor;
        }
      });
    }
  });

  return Object.entries(microTotals)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 6)
    .map(([key, value]) => [key, `${value.toFixed(value < 1 ? 2 : 0)}${getMicroUnit(key)}`]);
}

import { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { useSleepTracking, type SleepSession, type SleepPhase } from '../hooks/useSleepTracking';
import { useAppContext } from '../context/useAppContext';

const PHASE_COLORS: Record<SleepPhase, string> = {
  awake: 'bg-red-400',
  light: 'bg-blue-400',
  deep: 'bg-indigo-600',
  rem: 'bg-purple-400',
};

const PHASE_LABELS: Record<SleepPhase, string> = {
  awake: 'sleep.phases.awake',
  light: 'sleep.phases.light',
  deep: 'sleep.phases.deep',
  rem: 'sleep.phases.rem',
};

interface SleepDashboardProps {
  className?: string;
}

export default function SleepDashboard({ className = '' }: SleepDashboardProps) {
  const { t } = useTranslation();
  const { calcResults } = useAppContext();
  const {
    sessions,
    stats,
    settings,
    updateSettings,
    exportData,
    deleteAllData,
    currentSession,
  } = useSleepTracking();

  const [activeTab, setActiveTab] = useState<'overview' | 'trends' | 'correlations' | 'settings'>('overview');
  const [showExportModal, setShowExportModal] = useState(false);
  const [exportFormat, setExportFormat] = useState<'json' | 'csv'>('json');
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const chartCanvasRef = useRef<HTMLCanvasElement>(null);
  const weeklyChartRef = useRef<HTMLCanvasElement>(null);
  const monthlyChartRef = useRef<HTMLCanvasElement>(null);

  // Calculate sleep score
  const sleepScore = useMemo(() => {
    if (stats.totalSessions === 0) return 0;
    
    // Components: duration (25%), efficiency (25%), regularity (20%), latency (15%), phases (15%)
    const durationScore = Math.min(100, (stats.avgDuration / settings.targetDuration) * 100);
    const efficiencyScore = stats.avgEfficiency;
    
    // Regularity: standard deviation of bed/wake times over last 7 days
    const recentData = stats.weeklyTrend.filter(d => d.duration > 0);
    let regularityScore = 100;
    if (recentData.length >= 3) {
      const bedTimes = recentData.map(d => {
        const [h, m] = d.bedTime.split(':').map(Number);
        return h * 60 + m;
      });
      const wakeTimes = recentData.map(d => {
        const [h, m] = d.wakeTime.split(':').map(Number);
        return h * 60 + m;
      });
      
      const bedStdDev = calculateStdDev(bedTimes);
      const wakeStdDev = calculateStdDev(wakeTimes);
      const avgStdDev = (bedStdDev + wakeStdDev) / 2;
      // 30 min std dev = 100, 60 min = 70, 90 min = 40, 120+ = 0
      regularityScore = Math.max(0, 100 - (avgStdDev / 30) * 30);
    }
    
    // Latency score (lower is better, 0-30 min = 100, 60+ = 0)
    const avgLatency = sessions
      .filter(s => s.endTime)
      .slice(-7)
      .reduce((a, b) => a + b.sleepLatency, 0) / Math.max(1, sessions.filter(s => s.endTime).slice(-7).length);
    const latencyScore = Math.max(0, 100 - (avgLatency / 30) * 100);
    
    // Phase score (deep + REM percentage)
    const lastSession = sessions.filter(s => s.endTime).pop();
    let phaseScore = 50;
    if (lastSession) {
      const totalSleep = lastSession.phases
        .filter(p => p.phase !== 'awake')
        .reduce((a, b) => a + b.duration, 0);
      const deepPct = totalSleep > 0 ? (lastSession.phases.find(p => p.phase === 'deep')?.duration || 0) / totalSleep * 100 : 0;
      const remPct = totalSleep > 0 ? (lastSession.phases.find(p => p.phase === 'rem')?.duration || 0) / totalSleep * 100 : 0;
      phaseScore = Math.min(100, (deepPct * 2) + (remPct * 1.5) + 20);
    }
    
    const score = Math.round(
      durationScore * 0.25 +
      efficiencyScore * 0.25 +
      regularityScore * 0.20 +
      latencyScore * 0.15 +
      phaseScore * 0.15
    );
    
    return Math.max(0, Math.min(100, score));
  }, [stats, settings.targetDuration, sessions]);

  // Correlation data
  const correlations = useMemo(() => {
    if (!calcResults || sessions.length === 0) return null;
    
    const completedSessions = sessions.filter(s => s.endTime);
    if (completedSessions.length < 3) return null;
    
    // Sleep vs IBS symptoms (from diary would need context)
    // Sleep vs Workout (would need workout data)
    // Sleep vs Nutrition (from calcResults)
    
    return {
      sleepVsNutrition: {
        protein: calcResults.proteins,
        carbs: calcResults.carbs,
        fat: calcResults.fats,
        fiber: calcResults.fiber,
        water: calcResults.waterLiters,
      },
      sleepVsIBS: {
        // Would need diary data
        avgSymptomSeverity: 0,
        correlation: 0,
      },
      sleepVsWorkout: {
        // Would need workout data
        avgWorkoutIntensity: 0,
        correlation: 0,
      },
    };
  }, [calcResults, sessions]);

  const drawPhaseChart = useCallback(() => {
    const canvas = chartCanvasRef.current;
    if (!canvas) return;
    
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    
    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.scale(dpr, dpr);
    
    const width = rect.width;
    const height = rect.height;
    const centerX = width / 2;
    const centerY = height / 2;
    const radius = Math.min(width, height) / 2 - 20;
    
    ctx.clearRect(0, 0, width, height);
    
    // Get phase data from current session or last completed
    const session = currentSession || sessions.filter(s => s.endTime).pop();
    if (!session) {
      // Draw empty state
      ctx.font = '14px system-ui';
      ctx.fillStyle = 'var(--text-muted)';
      ctx.textAlign = 'center';
      ctx.fillText(t('sleep.dashboard.noData'), centerX, centerY);
      return;
    }
    
    const phaseTotals: Record<SleepPhase, number> = {
      awake: 0, light: 0, deep: 0, rem: 0,
    };
    session.phases.forEach(p => {
      phaseTotals[p.phase] += p.duration;
    });
    
    const totalSleep = phaseTotals.awake + phaseTotals.light + phaseTotals.deep + phaseTotals.rem;
    if (totalSleep === 0) return;
    
    let startAngle = -Math.PI / 2;
    const phases: SleepPhase[] = ['deep', 'rem', 'light', 'awake'];
    
    phases.forEach(phase => {
      const minutes = phaseTotals[phase];
      const percentage = minutes / totalSleep;
      const endAngle = startAngle + percentage * 2 * Math.PI;
      
      // Draw segment
      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, startAngle, endAngle);
      ctx.closePath();
      
      // Color based on phase
      const colors: Record<SleepPhase, string> = {
        awake: '#f87171',
        light: '#60a5fa',
        deep: '#4f46e5',
        rem: '#a855f7',
      };
      ctx.fillStyle = colors[phase];
      ctx.fill();
      
      // Draw label if segment is large enough
      if (percentage > 0.05) {
        const midAngle = startAngle + (endAngle - startAngle) / 2;
        const labelX = centerX + Math.cos(midAngle) * (radius * 0.6);
        const labelY = centerY + Math.sin(midAngle) * (radius * 0.6);
        
        ctx.font = 'bold 12px system-ui';
        ctx.fillStyle = 'white';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(`${Math.round(percentage * 100)}%`, labelX, labelY);
      }
      
      startAngle = endAngle;
    });
    
    // Center text
    ctx.font = 'bold 24px system-ui';
    ctx.fillStyle = 'var(--text-h)';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(`${Math.round(totalSleep)}'`, centerX, centerY - 10);
    
    ctx.font = '12px system-ui';
    ctx.fillStyle = 'var(--text-muted)';
    ctx.fillText(t('sleep.dashboard.totalSleep'), centerX, centerY + 15);
  }, [currentSession, sessions, t]);

  const drawWeeklyChart = useCallback(() => {
    const canvas = weeklyChartRef.current;
    if (!canvas) return;
    
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    
    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.scale(dpr, dpr);
    
    const width = rect.width;
    const height = rect.height;
    const padding = 40;
    const chartWidth = width - padding * 2;
    const chartHeight = height - padding * 2;
    
    ctx.clearRect(0, 0, width, height);
    
    const data = stats.weeklyTrend.filter(d => d.duration > 0);
    if (data.length === 0) {
      ctx.font = '12px system-ui';
      ctx.fillStyle = 'var(--text-muted)';
      ctx.textAlign = 'center';
      ctx.fillText(t('sleep.dashboard.noWeeklyData'), width / 2, height / 2);
      return;
    }
    
    const maxDuration = Math.max(...data.map(d => d.duration), settings.targetDuration);
    // Draw grid
    ctx.strokeStyle = 'var(--border)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 4; i++) {
      const y = padding + (chartHeight / 4) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(width - padding, y);
      ctx.stroke();
      
      // Y-axis labels
      const value = Math.round(maxDuration - (maxDuration / 4) * i);
      ctx.font = '10px system-ui';
      ctx.fillStyle = 'var(--text-muted)';
      ctx.textAlign = 'right';
      ctx.fillText(`${value}'`, padding - 5, y + 3);
    }
    
    // Draw target line
    const targetY = padding + chartHeight * (1 - settings.targetDuration / maxDuration);
    ctx.setLineDash([5, 5]);
    ctx.strokeStyle = 'var(--accent)';
    ctx.beginPath();
    ctx.moveTo(padding, targetY);
    ctx.lineTo(width - padding, targetY);
    ctx.stroke();
    ctx.setLineDash([]);
    
    // Draw bars
    const barWidth = chartWidth / data.length * 0.7;
    const barSpacing = chartWidth / data.length;
    
    data.forEach((day, i) => {
      const x = padding + i * barSpacing + (barSpacing - barWidth) / 2;
      const barHeight = (day.duration / maxDuration) * chartHeight;
      const y = padding + chartHeight - barHeight;
      
      // Bar color based on quality
      const quality = day.quality;
      let color = '#ef4444'; // red
      if (quality >= 80) color = '#22c55e'; // green
      else if (quality >= 60) color = '#eab308'; // yellow
      else if (quality >= 40) color = '#f97316'; // orange
      
      ctx.fillStyle = color;
      ctx.fillRect(x, y, barWidth, barHeight);
      
      // Day label
      ctx.font = '10px system-ui';
      ctx.fillStyle = 'var(--text-muted)';
      ctx.textAlign = 'center';
      const dayName = new Date(day.date).toLocaleDateString('it-IT', { weekday: 'short' });
      ctx.fillText(dayName, x + barWidth / 2, height - padding / 2 + 15);
    });
    
    // Y-axis label
    ctx.save();
    ctx.translate(15, height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.font = '11px system-ui';
    ctx.fillStyle = 'var(--text-muted)';
    ctx.textAlign = 'center';
    ctx.fillText(t('sleep.dashboard.durationMinutes'), 0, 0);
    ctx.restore();
  }, [stats, settings.targetDuration, t]);

  const drawMonthlyChart = useCallback(() => {
    const canvas = monthlyChartRef.current;
    if (!canvas) return;
    
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    
    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.scale(dpr, dpr);
    
    const width = rect.width;
    const height = rect.height;
    const padding = 40;
    const chartWidth = width - padding * 2;
    const chartHeight = height - padding * 2;
    
    ctx.clearRect(0, 0, width, height);
    
    const data = stats.monthlyTrend.filter(d => d.duration > 0);
    if (data.length === 0) {
      ctx.font = '12px system-ui';
      ctx.fillStyle = 'var(--text-muted)';
      ctx.textAlign = 'center';
      ctx.fillText(t('sleep.dashboard.noMonthlyData'), width / 2, height / 2);
      return;
    }
    
    // Group by week for monthly view
    const weeklyAvg: { week: string; avgDuration: number; avgQuality: number }[] = [];
    for (let i = 0; i < data.length; i += 7) {
      const weekData = data.slice(i, i + 7);
      if (weekData.length === 0) continue;
      const avgDur = weekData.reduce((a, b) => a + b.duration, 0) / weekData.length;
      const avgQual = weekData.reduce((a, b) => a + b.quality, 0) / weekData.length;
      weeklyAvg.push({
        week: `${weekData[0].date} - ${weekData[weekData.length - 1].date}`,
        avgDuration: avgDur,
        avgQuality: avgQual,
      });
    }
    
    const maxDuration = Math.max(...weeklyAvg.map(d => d.avgDuration), settings.targetDuration);
    
    // Draw grid
    ctx.strokeStyle = 'var(--border)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 4; i++) {
      const y = padding + (chartHeight / 4) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(width - padding, y);
      ctx.stroke();
      
      const value = Math.round(maxDuration - (maxDuration / 4) * i);
      ctx.font = '10px system-ui';
      ctx.fillStyle = 'var(--text-muted)';
      ctx.textAlign = 'right';
      ctx.fillText(`${value}'`, padding - 5, y + 3);
    }
    
    // Target line
    const targetY = padding + chartHeight * (1 - settings.targetDuration / maxDuration);
    ctx.setLineDash([5, 5]);
    ctx.strokeStyle = 'var(--accent)';
    ctx.beginPath();
    ctx.moveTo(padding, targetY);
    ctx.lineTo(width - padding, targetY);
    ctx.stroke();
    ctx.setLineDash([]);
    
    // Draw line chart for duration
    ctx.strokeStyle = 'var(--accent)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    
    weeklyAvg.forEach((week, i) => {
      const x = padding + (i / (weeklyAvg.length - 1 || 1)) * chartWidth;
      const y = padding + chartHeight * (1 - week.avgDuration / maxDuration);
      
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();
    
    // Draw points
    weeklyAvg.forEach((week, i) => {
      const x = padding + (i / (weeklyAvg.length - 1 || 1)) * chartWidth;
      const y = padding + chartHeight * (1 - week.avgDuration / maxDuration);
      
      ctx.fillStyle = 'var(--accent)';
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    });
    
    // Week labels
    ctx.font = '9px system-ui';
    ctx.fillStyle = 'var(--text-muted)';
    ctx.textAlign = 'center';
    weeklyAvg.forEach((_, i) => {
      const x = padding + (i / (weeklyAvg.length - 1 || 1)) * chartWidth;
      const weekNum = Math.floor(i + 1);
      ctx.fillText(`${t('sleep.dashboard.week')} ${weekNum}`, x, height - padding / 2 + 15);
    });
    
    // Y-axis label
    ctx.save();
    ctx.translate(15, height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.font = '11px system-ui';
    ctx.fillStyle = 'var(--text-muted)';
    ctx.textAlign = 'center';
    ctx.fillText(t('sleep.dashboard.avgDuration'), 0, 0);
    ctx.restore();
  }, [stats, settings.targetDuration, t]);

  // Draw charts after all callbacks are initialized.
  useEffect(() => {
    drawPhaseChart();
    drawWeeklyChart();
    drawMonthlyChart();
  }, [drawPhaseChart, drawWeeklyChart, drawMonthlyChart]);

  const calculateStdDev = (values: number[]): number => {
    if (values.length === 0) return 0;
    const mean = values.reduce((a, b) => a + b, 0) / values.length;
    const variance = values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length;
    return Math.sqrt(variance);
  };

  const formatDuration = (minutes: number) => {
    const h = Math.floor(minutes / 60);
    const m = minutes % 60;
    return `${h}h ${m}m`;
  };

  const getScoreColor = (score: number) => {
    if (score >= 80) return 'text-emerald-500';
    if (score >= 60) return 'text-yellow-500';
    if (score >= 40) return 'text-orange-500';
    return 'text-red-500';
  };

  const getScoreLabel = (score: number) => {
    if (score >= 80) return t('sleep.dashboard.excellent');
    if (score >= 60) return t('sleep.dashboard.good');
    if (score >= 40) return t('sleep.dashboard.fair');
    return t('sleep.dashboard.poor');
  };

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Header with Score */}
      <div className="bg-(--card-bg) border border-(--border) rounded-2xl p-6">
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-6">
          <div className="flex items-center gap-4">
            <div className="w-20 h-20 rounded-2xl bg-gradient-to-br from-(--accent) to-(--accent-hover) flex items-center justify-center">
              <span className="text-3xl">🌙</span>
            </div>
            <div>
              <h2 className="text-2xl font-bold text-(--text-h)">{t('sleep.dashboard.title')}</h2>
              <p className="text-(--text-muted) text-sm">{t('sleep.dashboard.subtitle')}</p>
            </div>
          </div>
          
          <div className="flex flex-col items-center md:items-end gap-2">
            <div className="relative w-32 h-32">
              <canvas 
                ref={chartCanvasRef} 
                className="w-full h-full" 
                width={128} 
                height={128}
                aria-label={t('sleep.dashboard.sleepScoreAria', { score: sleepScore })}
              />
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <span className={`text-3xl font-bold ${getScoreColor(sleepScore)}`}>{sleepScore}</span>
                <span className="text-xs text-(--text-muted)">{getScoreLabel(sleepScore)}</span>
              </div>
            </div>
            <p className="text-xs text-(--text-muted) text-center md:text-right">
              {t('sleep.dashboard.basedOn', { count: stats.totalSessions })}
            </p>
          </div>
        </div>
      </div>

      {/* Tab Navigation */}
      <div className="flex gap-2 overflow-x-auto pb-2" role="tablist">
        {[
          { id: 'overview', label: t('sleep.dashboard.tabOverview'), icon: '📊' },
          { id: 'trends', label: t('sleep.dashboard.tabTrends'), icon: '📈' },
          { id: 'correlations', label: t('sleep.dashboard.tabCorrelations'), icon: '🔗' },
          { id: 'settings', label: t('sleep.dashboard.tabSettings'), icon: '⚙️' },
        ].map(tab => (
          <button
            key={tab.id}
            role="tab"
            aria-selected={activeTab === tab.id}
            onClick={() => setActiveTab(tab.id as typeof activeTab)}
            className={`flex items-center gap-1.5 px-4 py-2 rounded-xl text-sm font-medium whitespace-nowrap transition-all ${
              activeTab === tab.id
                ? 'bg-(--accent) text-white'
                : 'bg-(--card-bg) border border-(--border) text-(--text) hover:text-(--text-h) hover:border-(--accent-border)'
            }`}
          >
            <span aria-hidden="true">{tab.icon}</span>
            {tab.label}
          </button>
        ))}
      </div>

      {/* Tab Content */}
      <div className="bg-(--card-bg) border border-(--border) rounded-2xl p-6">
        {activeTab === 'overview' && (
          <div className="space-y-6">
            {/* Key Metrics Grid */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <MetricCard
                label={t('sleep.dashboard.totalSleep')}
                value={formatDuration(stats.avgDuration)}
                icon="⏱️"
                target={formatDuration(settings.targetDuration)}
              />
              <MetricCard
                label={t('sleep.dashboard.efficiency')}
                value={`${stats.avgEfficiency}%`}
                icon="⚡"
                target={`${Math.round((settings.targetDuration * 0.85) / settings.targetDuration * 100)}%`}
              />
              <MetricCard
                label={t('sleep.dashboard.sleepLatency')}
                value={
                  sessions.filter(s => s.endTime).length > 0
                    ? `${Math.round(sessions.filter(s => s.endTime).slice(-7).reduce((a, b) => a + b.sleepLatency, 0) / Math.max(1, sessions.filter(s => s.endTime).slice(-7).length))} min`
                    : '--'
                }
                icon="💤"
                target="< 20 min"
              />
              <MetricCard
                label={t('sleep.dashboard.sleepDebt')}
                value={formatDuration(stats.totalSleepDebt)}
                icon="💳"
                target="0 min"
                isNegative={stats.totalSleepDebt > 0}
              />
            </div>

            {/* Phase Breakdown */}
            <div>
              <h3 className="text-lg font-semibold text-(--text-h) mb-4">{t('sleep.dashboard.phaseBreakdown')}</h3>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {(['deep', 'rem', 'light', 'awake'] as SleepPhase[]).map(phase => {
                  const lastSession = currentSession || sessions.filter(s => s.endTime).pop();
                  const minutes = lastSession?.phases
                    .filter(p => p.phase === phase)
                    .reduce((a, b) => a + b.duration, 0) || 0;
                  const total = lastSession?.phases
                    .filter(p => p.phase !== 'awake')
                    .reduce((a, b) => a + b.duration, 0) || 1;
                  const percentage = Math.round((minutes / total) * 100);
                  
                  return (
                    <div key={phase} className="p-4 rounded-xl bg-(--bg) border border-(--border)">
                      <div className="flex items-center gap-2 mb-2">
                        <div className={`w-3 h-3 rounded ${PHASE_COLORS[phase]}`} />
                        <span className="font-medium text-(--text-h)">{t(PHASE_LABELS[phase])}</span>
                      </div>
                      <div className="text-2xl font-bold text-(--text-h)">{minutes} min</div>
                      <div className="text-xs text-(--text-muted)">{percentage}% {t('sleep.dashboard.ofSleepTime')}</div>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Last Session Details */}
            {currentSession && (
              <div className="p-4 rounded-xl bg-(--accent)/10 border border-(--accent)/30">
                <h3 className="font-semibold text-(--text-h) mb-2 flex items-center gap-2">
                  <span className="animate-pulse text-(--accent)">●</span>
                  {t('sleep.dashboard.trackingActive')}
                </h3>
                <div className="grid grid-cols-3 gap-4 text-sm">
                  <div>
                    <div className="text-(--text-muted)">{t('sleep.dashboard.elapsed')}</div>
                    <div className="font-bold text-(--text-h)">{Math.round((Date.now() - currentSession.startTime) / 60000)} min</div>
                  </div>
                  <div>
                    <div className="text-(--text-muted)">{t('sleep.dashboard.currentPhase')}</div>
                    <div className="font-bold text-(--text-h) capitalize">{t(PHASE_LABELS[currentSession.phases[currentSession.phases.length - 1]?.phase || 'awake'])}</div>
                  </div>
                  <div>
                    <div className="text-(--text-muted)">{t('sleep.dashboard.bedTime')}</div>
                    <div className="font-bold text-(--text-h)">{new Date(currentSession.startTime).toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit' })}</div>
                  </div>
                </div>
              </div>
            )}

            {/* Recent Sessions */}
            <div>
              <h3 className="text-lg font-semibold text-(--text-h) mb-4">{t('sleep.dashboard.recentSessions')}</h3>
              {sessions.filter(s => s.endTime).slice(-5).reverse().length === 0 ? (
                <p className="text-(--text-muted) text-center py-8">{t('sleep.dashboard.noSessionsYet')}</p>
              ) : (
                <div className="space-y-2">
                  {sessions.filter(s => s.endTime).slice(-5).reverse().map(session => (
                    <SessionRow key={session.id} session={session} />
                  ))}
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'trends' && (
          <div className="space-y-6">
            {/* Weekly Trend */}
            <div>
              <h3 className="text-lg font-semibold text-(--text-h) mb-4">{t('sleep.dashboard.weeklyTrend')}</h3>
              <div className="h-64">
                <canvas ref={weeklyChartRef} className="w-full h-full" />
              </div>
              <div className="flex justify-center gap-6 mt-4 text-sm">
                <span className="flex items-center gap-1.5">
                  <div className="w-3 h-3 rounded bg-emerald-500" />
                  {t('sleep.dashboard.goodQuality')}
                </span>
                <span className="flex items-center gap-1.5">
                  <div className="w-3 h-3 rounded bg-yellow-500" />
                  {t('sleep.dashboard.mediumQuality')}
                </span>
                <span className="flex items-center gap-1.5">
                  <div className="w-3 h-3 rounded bg-red-500" />
                  {t('sleep.dashboard.poorQuality')}
                </span>
                <span className="flex items-center gap-1.5">
                  <div className="w-3 h-3 rounded border border-dashed border-(--accent) bg-transparent" />
                  {t('sleep.dashboard.target')}
                </span>
              </div>
            </div>

            {/* Monthly Trend */}
            <div>
              <h3 className="text-lg font-semibold text-(--text-h) mb-4">{t('sleep.dashboard.monthlyTrend')}</h3>
              <div className="h-64">
                <canvas ref={monthlyChartRef} className="w-full h-full" />
              </div>
              <p className="text-sm text-(--text-muted) mt-2 text-center">
                {t('sleep.dashboard.monthlyTrendDesc')}
              </p>
            </div>

            {/* Weekly Data Table */}
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-left text-(--text-muted) border-b border-(--border)">
                    <th className="pb-2 px-2">{t('sleep.dashboard.date')}</th>
                    <th className="pb-2 px-2">{t('sleep.dashboard.bedTime')}</th>
                    <th className="pb-2 px-2">{t('sleep.dashboard.wakeTime')}</th>
                    <th className="pb-2 px-2">{t('sleep.dashboard.duration')}</th>
                    <th className="pb-2 px-2">{t('sleep.dashboard.efficiency')}</th>
                    <th className="pb-2 px-2">{t('sleep.dashboard.quality')}</th>
                    <th className="pb-2 px-2">{t('sleep.dashboard.deepSleep')}</th>
                    <th className="pb-2 px-2">{t('sleep.dashboard.remSleep')}</th>
                  </tr>
                </thead>
                <tbody>
                  {stats.weeklyTrend.map(day => (
                    <tr key={day.date} className="border-b border-(--border)/50 hover:bg-(--accent)/5">
                      <td className="py-2 px-2 font-mono">{new Date(day.date).toLocaleDateString('it-IT')}</td>
                      <td className="py-2 px-2">{day.bedTime}</td>
                      <td className="py-2 px-2">{day.wakeTime}</td>
                      <td className="py-2 px-2">{day.duration > 0 ? formatDuration(day.duration) : '-'}</td>
                      <td className="py-2 px-2">{day.efficiency > 0 ? `${day.efficiency}%` : '-'}</td>
                      <td className="py-2 px-2">
                        {day.quality > 0 ? (
                          <span className={getScoreColor(day.quality)}>{day.quality}</span>
                        ) : '-'}
                      </td>
                      <td className="py-2 px-2">{day.phases.deep > 0 ? `${day.phases.deep} min` : '-'}</td>
                      <td className="py-2 px-2">{day.phases.rem > 0 ? `${day.phases.rem} min` : '-'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'correlations' && (
          <div className="space-y-6">
            <div className="p-4 rounded-xl bg-(--accent)/10 border border-(--accent)/30">
              <h3 className="font-semibold text-(--text-h) mb-2 flex items-center gap-2">
                <span>🔬</span>
                {t('sleep.dashboard.correlationsTitle')}
              </h3>
              <p className="text-sm text-(--text-muted)">{t('sleep.dashboard.correlationsDesc')}</p>
            </div>

            <div className="grid md:grid-cols-3 gap-4">
              {/* Sleep vs Nutrition */}
              <div className="p-4 rounded-xl bg-(--card-bg) border border-(--border)">
                <h4 className="font-semibold text-(--text-h) mb-3 flex items-center gap-2">
                  <span>🍽️</span>
                  {t('sleep.dashboard.nutritionCorrelation')}
                </h4>
                {correlations ? (
                  <div className="space-y-2 text-sm">
                    <CorrelationRow label={t('sleep.dashboard.protein')} value={`${correlations.sleepVsNutrition.protein}g`} />
                    <CorrelationRow label={t('sleep.dashboard.carbs')} value={`${correlations.sleepVsNutrition.carbs}g`} />
                    <CorrelationRow label={t('sleep.dashboard.fat')} value={`${correlations.sleepVsNutrition.fat}g`} />
                    <CorrelationRow label={t('sleep.dashboard.fiber')} value={`${correlations.sleepVsNutrition.fiber}g`} />
                    <CorrelationRow label={t('sleep.dashboard.water')} value={`${correlations.sleepVsNutrition.water}L`} />
                  </div>
                ) : (
                  <p className="text-(--text-muted) text-sm">{t('sleep.dashboard.needCalculation')}</p>
                )}
              </div>

              {/* Sleep vs IBS Symptoms */}
              <div className="p-4 rounded-xl bg-(--card-bg) border border-(--border)">
                <h4 className="font-semibold text-(--text-h) mb-3 flex items-center gap-2">
                  <span>🫃</span>
                  {t('sleep.dashboard.ibsCorrelation')}
                </h4>
                <p className="text-sm text-(--text-muted) mb-3">{t('sleep.dashboard.ibsCorrelationDesc')}</p>
                <div className="space-y-2 text-sm">
                  <CorrelationRow label={t('sleep.dashboard.avgSymptoms')} value="—" />
                  <CorrelationRow label={t('sleep.dashboard.correlation')} value="—" />
                </div>
                <button 
                  className="mt-3 text-xs text-(--accent) hover:underline"
                  onClick={() => window.history.pushState(null, '', '/diary')}
                >
                  {t('sleep.dashboard.goToDiary')}
                </button>
              </div>

              {/* Sleep vs Workout */}
              <div className="p-4 rounded-xl bg-(--card-bg) border border-(--border)">
                <h4 className="font-semibold text-(--text-h) mb-3 flex items-center gap-2">
                  <span>💪</span>
                  {t('sleep.dashboard.workoutCorrelation')}
                </h4>
                <p className="text-sm text-(--text-muted) mb-3">{t('sleep.dashboard.workoutCorrelationDesc')}</p>
                <div className="space-y-2 text-sm">
                  <CorrelationRow label={t('sleep.dashboard.avgIntensity')} value="—" />
                  <CorrelationRow label={t('sleep.dashboard.correlation')} value="—" />
                </div>
                <button 
                  className="mt-3 text-xs text-(--accent) hover:underline"
                  onClick={() => window.history.pushState(null, '', '/workout')}
                >
                  {t('sleep.dashboard.goToWorkout')}
                </button>
              </div>
            </div>

            {/* Insights */}
            <div className="p-4 rounded-xl bg-(--bg) border border-(--border)">
              <h4 className="font-semibold text-(--text-h) mb-3 flex items-center gap-2">
                <span>💡</span>
                {t('sleep.dashboard.insights')}
              </h4>
              <div className="space-y-2 text-sm text-(--text)">
                {sleepScore < 60 && (
                  <InsightItem 
                    type="warning" 
                    text={t('sleep.dashboard.insightLowScore')} 
                  />
                )}
                {stats.totalSleepDebt > 120 && (
                  <InsightItem 
                    type="warning" 
                    text={t('sleep.dashboard.insightSleepDebt', { debt: formatDuration(stats.totalSleepDebt) })} 
                  />
                )}
                {stats.avgEfficiency < 80 && (
                  <InsightItem 
                    type="info" 
                    text={t('sleep.dashboard.insightLowEfficiency')} 
                  />
                )}
                {sessions.length === 0 && (
                  <InsightItem 
                    type="info" 
                    text={t('sleep.dashboard.insightNoData')} 
                  />
                )}
                {sleepScore >= 80 && stats.totalSessions > 0 && (
                  <InsightItem 
                    type="success" 
                    text={t('sleep.dashboard.insightGreatJob')} 
                  />
                )}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'settings' && (
          <div className="space-y-6">
            <div className="space-y-4">
              <h3 className="text-lg font-semibold text-(--text-h)">{t('sleep.dashboard.settings')}</h3>
              
              <SettingItem>
                <SettingLabel>
                  {t('sleep.dashboard.targetDuration')}
                  <span className="text-sm text-(--text-muted) ml-2">({t('sleep.dashboard.minutes')})</span>
                </SettingLabel>
                <input
                  type="number"
                  min="300"
                  max="600"
                  step="15"
                  value={settings.targetDuration}
                  onChange={e => updateSettings({ targetDuration: parseInt(e.target.value) || 480 })}
                  className="w-24 px-3 py-2 rounded-lg border border-(--border) bg-(--bg) text-(--text) text-right"
                />
              </SettingItem>

              <SettingItem>
                <SettingLabel>{t('sleep.dashboard.bedtimeReminder')}</SettingLabel>
                <label className="relative inline-flex items-center cursor-pointer">
                  <input
                    type="checkbox"
                    checked={settings.bedtimeReminder}
                    onChange={e => updateSettings({ bedtimeReminder: e.target.checked })}
                    className="sr-only peer"
                  />
                  <div className="w-11 h-6 bg-(--border) peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-(--accent)/30 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-(--accent)"></div>
                </label>
              </SettingItem>

              <SettingItem>
                <SettingLabel>{t('sleep.dashboard.bedtimeReminderTime')}</SettingLabel>
                <input
                  type="time"
                  value={settings.bedtimeReminderTime}
                  onChange={e => updateSettings({ bedtimeReminderTime: e.target.value })}
                  className="px-3 py-2 rounded-lg border border-(--border) bg-(--bg) text-(--text) w-32"
                />
              </SettingItem>

              <SettingItem>
                <SettingLabel>{t('sleep.dashboard.windDownDuration')}</SettingLabel>
                <select
                  value={settings.windDownDuration}
                  onChange={e => updateSettings({ windDownDuration: parseInt(e.target.value) })}
                  className="px-3 py-2 rounded-lg border border-(--border) bg-(--bg) text-(--text) w-32"
                >
                  <option value={15}>{t('sleep.dashboard.minutes', { count: 15 })}</option>
                  <option value={30}>{t('sleep.dashboard.minutes', { count: 30 })}</option>
                  <option value={45}>{t('sleep.dashboard.minutes', { count: 45 })}</option>
                  <option value={60}>{t('sleep.dashboard.minutes', { count: 60 })}</option>
                </select>
              </SettingItem>

              <SettingItem>
                <SettingLabel>{t('sleep.dashboard.wakeLockEnabled')}</SettingLabel>
                <label className="relative inline-flex items-center cursor-pointer">
                  <input
                    type="checkbox"
                    checked={settings.wakeLockEnabled}
                    onChange={e => updateSettings({ wakeLockEnabled: e.target.checked })}
                    className="sr-only peer"
                  />
                  <div className="w-11 h-6 bg-(--border) peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-(--accent)/30 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-(--accent)"></div>
                </label>
              </SettingItem>

              <SettingItem>
                <SettingLabel>{t('sleep.dashboard.sensitivity')}</SettingLabel>
                <select
                  value={settings.sensitivity}
                  onChange={e => updateSettings({ sensitivity: e.target.value as 'low' | 'medium' | 'high' })}
                  className="px-3 py-2 rounded-lg border border-(--border) bg-(--bg) text-(--text) w-40"
                >
                  <option value="low">{t('sleep.dashboard.low')}</option>
                  <option value="medium">{t('sleep.dashboard.medium')}</option>
                  <option value="high">{t('sleep.dashboard.high')}</option>
                </select>
              </SettingItem>
            </div>

            {/* Data Management */}
            <div className="pt-6 border-t border-(--border) space-y-4">
              <h3 className="text-lg font-semibold text-(--text-h)">{t('sleep.dashboard.dataManagement')}</h3>
              
              <div className="flex flex-wrap gap-3">
                <button
                  onClick={() => { setExportFormat('json'); setShowExportModal(true); }}
                  className="px-4 py-2 rounded-lg border border-(--border) bg-(--card-bg) text-(--text) hover:bg-(--accent)/10 hover:border-(--accent-border) transition-colors text-sm"
                >
                  📥 {t('sleep.dashboard.exportJSON')}
                </button>
                <button
                  onClick={() => { setExportFormat('csv'); setShowExportModal(true); }}
                  className="px-4 py-2 rounded-lg border border-(--border) bg-(--card-bg) text-(--text) hover:bg-(--accent)/10 hover:border-(--accent-border) transition-colors text-sm"
                >
                  📊 {t('sleep.dashboard.exportCSV')}
                </button>
                <button
                  onClick={() => setShowDeleteConfirm(true)}
                  className="px-4 py-2 rounded-lg border border-red-500/30 bg-red-500/10 text-red-500 hover:bg-red-500/20 transition-colors text-sm"
                >
                  🗑️ {t('sleep.dashboard.deleteAllData')}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Export Modal */}
      {showExportModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
          <div className="bg-(--card-bg) border border-(--border) rounded-2xl p-6 w-full max-w-md">
            <h3 className="text-lg font-semibold text-(--text-h) mb-4">{t('sleep.dashboard.exportData')}</h3>
            <p className="text-sm text-(--text-muted) mb-4">
              {exportFormat === 'json' 
                ? t('sleep.dashboard.exportJSONDesc') 
                : t('sleep.dashboard.exportCSVDesc')
              }
            </p>
            <div className="flex gap-3 justify-end">
              <button
                onClick={() => setShowExportModal(false)}
                className="px-4 py-2 rounded-lg border border-(--border) bg-(--card-bg) text-(--text) hover:bg-(--accent)/10 transition-colors"
              >
                {t('common.cancel')}
              </button>
              <button
                onClick={() => { exportData(exportFormat); setShowExportModal(false); }}
                className="px-4 py-2 rounded-lg bg-(--accent) text-white hover:bg-(--accent-hover) transition-colors"
              >
                {t('sleep.dashboard.export')}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirm Modal */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
          <div className="bg-(--card-bg) border border-(--border) rounded-2xl p-6 w-full max-w-md">
            <h3 className="text-lg font-semibold text-(--text-h) mb-2">{t('sleep.dashboard.confirmDelete')}</h3>
            <p className="text-sm text-(--text-muted) mb-6">{t('sleep.dashboard.confirmDeleteDesc')}</p>
            <div className="flex gap-3 justify-end">
              <button
                onClick={() => setShowDeleteConfirm(false)}
                className="px-4 py-2 rounded-lg border border-(--border) bg-(--card-bg) text-(--text) hover:bg-(--accent)/10 transition-colors"
              >
                {t('common.cancel')}
              </button>
              <button
                onClick={() => { deleteAllData(); setShowDeleteConfirm(false); }}
                className="px-4 py-2 rounded-lg bg-red-500 text-white hover:bg-red-600 transition-colors"
              >
                {t('sleep.dashboard.delete')}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ============================================
// Helper Components
// ============================================

function MetricCard({ label, value, icon, target, isNegative = false }: {
  label: string;
  value: string;
  icon: string;
  target: string;
  isNegative?: boolean;
}) {
  return (
    <div className="p-4 rounded-xl bg-(--bg) border border-(--border)">
      <div className="flex items-center gap-2 mb-2">
        <span className="text-xl">{icon}</span>
        <span className="text-sm text-(--text-muted)">{label}</span>
      </div>
      <div className="text-2xl font-bold text-(--text-h)">{value}</div>
      <div className="text-xs text-(--text-muted) mt-1">
        {isNegative ? '⚠️ ' : '🎯 '}{target}
      </div>
    </div>
  );
}

function SessionRow({ session }: { session: SleepSession }) {
  const date = new Date(session.startTime);
  const bedTime = date.toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit' });
  const wakeTime = session.endTime
    ? new Date(session.endTime).toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit' })
    : '--:--';
  const qualityColor = session.quality >= 80 ? 'text-emerald-500' : 
                       session.quality >= 60 ? 'text-yellow-500' : 
                       session.quality >= 40 ? 'text-orange-500' : 'text-red-500';
  
  return (
    <div className="p-3 rounded-lg bg-(--bg) border border-(--border) flex items-center justify-between gap-4">
      <div className="flex items-center gap-3 min-w-0">
        <div className="w-10 h-10 rounded-lg bg-(--accent)/10 flex items-center justify-center flex-shrink-0">
          <span className="text-lg">🌙</span>
        </div>
        <div className="min-w-0">
          <div className="font-medium text-(--text-h) truncate">
            {date.toLocaleDateString('it-IT', { weekday: 'short', day: 'numeric', month: 'short' })}
          </div>
          <div className="text-xs text-(--text-muted) flex items-center gap-2">
            <span>{bedTime} - {wakeTime}</span>
            <span>•</span>
            <span>{formatDuration(session.duration)}</span>
          </div>
        </div>
      </div>
      <div className="flex items-center gap-4 text-sm flex-shrink-0">
        <div className={`font-bold ${qualityColor}`}>{session.quality}</div>
        <div className="text-(--text-muted)">{session.efficiency}%</div>
      </div>
    </div>
  );
}

function CorrelationRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex justify-between text-sm">
      <span className="text-(--text-muted)">{label}</span>
      <span className="font-medium text-(--text-h)">{value}</span>
    </div>
  );
}

function InsightItem({ type, text }: { type: 'success' | 'warning' | 'info'; text: string }) {
  const icons = { success: '✅', warning: '⚠️', info: 'ℹ️' };
  const colors = { 
    success: 'bg-emerald-500/10 border-emerald-500/30 text-emerald-600', 
    warning: 'bg-yellow-500/10 border-yellow-500/30 text-yellow-600', 
    info: 'bg-blue-500/10 border-blue-500/30 text-blue-600' 
  };
  
  return (
    <div className={`p-3 rounded-lg border flex items-start gap-2 ${colors[type]}`}>
      <span className="text-lg mt-0.5">{icons[type]}</span>
      <span className="text-sm">{text}</span>
    </div>
  );
}

function SettingItem({ children }: { children: React.ReactNode }) {
  return <div className="flex items-center justify-between py-2">{children}</div>;
}

function SettingLabel({ children }: { children: React.ReactNode }) {
  return <label className="text-sm font-medium text-(--text-h) flex items-center gap-2">{children}</label>;
}

