              ›
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ============================================
// LEGACY buildSuggestedPlan (per compatibilità)
// ============================================
function buildSuggestedPlan(
  suggestion: { moreCardio: boolean; moreStrength: boolean; lowImpact: boolean },
  t: (key: string, options?: Record<string, unknown>) => string
): Record<DayKey, DayPlan> {
  const base = getDefaultPlan(t);

  const pick = (candidates: string[], day: DayKey) => {
    const id = candidates.find(ex => EXERCISES[ex]) ?? 'walk';
    return {
      ...base[day],
      exerciseId: id,
      activity: t(`workout_${id}_activity`, { defaultValue: DEFAULT_ACTIVITIES[id] }),
      duration: suggestedDuration(id)
    };
  };

  let plan: Record<DayKey, DayPlan>;

  if (suggestion.lowImpact) {
    plan = {
      mon: pick(['walk', 'swim'], 'mon'),
      tue: pick(['yoga', 'plank'], 'tue'),
      wed: pick(['walk', 'free'], 'wed'),
      thu: pick(['yoga', 'plank'], 'thu'),
      fri: pick(['walk', 'swim'], 'fri'),
      sat: pick(['free', 'swim'], 'sat'),
      sun: pick(['rest', 'breathe'], 'sun')
    };
  } else if (suggestion.moreStrength && !suggestion.moreCardio) {
    plan = {
      mon: pick(['squat', 'lunge'], 'mon'),
      tue: pick(['pushup', 'row'], 'tue'),
      wed: pick(['biceps_curl', 'shoulder_press'], 'wed'),
      thu: pick(['squat', 'calf_raise'], 'thu'),
      fri: pick(['pushup', 'row'], 'fri'),
      sat: pick(['free', 'swim'], 'sat'),
      sun: pick(['rest', 'yoga'], 'sun')
    };
  } else if (suggestion.moreCardio && !suggestion.moreStrength) {
    plan = {
      mon: pick(['walk', 'swim'], 'mon'),
      tue: pick(['burpees', 'free'], 'tue'),
      wed: pick(['walk', 'swim'], 'wed'),
      thu: pick(['free', 'burpees'], 'thu'),
      fri: pick(['walk', 'swim'], 'fri'),
      sat: pick(['free', 'swim'], 'sat'),
      sun: pick(['rest', 'yoga'], 'sun')
    };
  } else {
    plan = {
      mon: pick(['walk', 'swim'], 'mon'),
      tue: pick(['squat', 'lunge'], 'tue'),
      wed: pick(['yoga', 'plank'], 'wed'),
      thu: pick(['pushup', 'row'], 'thu'),
      fri: pick(['biceps_curl', 'shoulder_press'], 'fri'),
      sat: pick(['free', 'swim'], 'sat'),
      sun: pick(['rest', 'yoga'], 'sun')
    };
  }

  return plan;
}

import { useState, useCallback, useEffect } from 'react';
import type { ReactNode } from 'react';
import type { TabId } from './AppContextTypes';
import type { NutritionalResults, UserData } from '../utils/nutritionEngine';
import { useDietPlan } from '../hooks/useDietPlan';
import { calcStorage, userDataStorage, dietStartDateStorage } from '../utils/storage';
import AppContext from './AppContext.ts';

interface AppProviderProps {
  children: ReactNode;
  setActiveTab?: (tab: TabId) => void;
}

export function AppProvider({ children, setActiveTab }: AppProviderProps) {
  const [calcResults, setCalcResults] = useState<NutritionalResults | null>(() => calcStorage.get());
  const [userData, setUserData] = useState<UserData | null>(() => userDataStorage.get());
  const [dietStartDate, setDietStartDate] = useState<string | null>(() => dietStartDateStorage.get());

  const dietPlan = useDietPlan(calcResults, userData, dietStartDate);

  // Trigger diet plan generation whenever calculator results become available
  useEffect(() => {
    if (calcResults) {
      dietPlan.regenerateDays(calcResults, userData);
    }
  }, [calcResults, userData, dietPlan]);

  const handleCalculate = useCallback((results: NutritionalResults, data: UserData) => {
    setCalcResults(results);
    setUserData(data);
    
    // Set diet start date if not already set (first calculation)
    if (!dietStartDate) {
      const today = new Date().toISOString().split('T')[0];
      setDietStartDate(today);
      dietStartDateStorage.set(today);
    }
  }, [dietStartDate]);

  // Persist calculator results whenever they change (e.g. loaded from context or set externally)
  useEffect(() => {
    if (calcResults) {
      calcStorage.set(calcResults);
    }
  }, [calcResults]);

  // Persist user data whenever it changes
  useEffect(() => {
    if (userData) {
      userDataStorage.set(userData);
    }
  }, [userData]);

  // Provide a no-op setActiveTab for compatibility with components that still use it
  const noopSetActiveTab = useCallback((_tab: TabId) => {
    // Navigation is now handled by react-router-dom
  }, []);

  return (
    <AppContext.Provider value={{
      calcResults,
      userData,
      dietPlan,
      setCalcResults,
      setUserData,
      handleCalculate,
      setActiveTab: setActiveTab || noopSetActiveTab,
      dietStartDate,
      setDietStartDate
    }}>
      {children}
    </AppContext.Provider>
  );
}

